package app.layan.quran.prayer;
import android.app.*;import android.appwidget.*;import android.content.*;import android.content.res.*;import android.content.pm.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.util.*;import java.util.concurrent.*;import org.threeten.bp.*;import org.threeten.bp.format.DateTimeFormatter;import app.layan.quran.*;
/** Prayer widgets use saved foreground location and the same reference engine as the prayer section. */
public abstract class PrayerWidget extends AppWidgetProvider {
 public static final class Horizontal extends PrayerWidget{protected String kind(){return "horizontal";}}
 public static final class Vertical extends PrayerWidget{protected String kind(){return "vertical";}}
 public static final class Mini extends PrayerWidget{protected String kind(){return "mini";}}
 public static final class Minimal extends PrayerWidget{protected String kind(){return "minimal";}}
 public static final class Clock extends PrayerWidget{protected String kind(){return "clock";}}
 private static final Class<?>[] TYPES={Horizontal.class,Vertical.class,Mini.class,Minimal.class,Clock.class};protected abstract String kind();
 private static final ExecutorService WORKER=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"LayanWidget");t.setDaemon(true);return t;});
 @Override public void onReceive(Context context,Intent intent){String action=intent.getAction();if(action==null)return;if(action.equals(AppWidgetManager.ACTION_APPWIDGET_DELETED)||action.equals(AppWidgetManager.ACTION_APPWIDGET_DISABLED)){super.onReceive(context,intent);return;}PendingResult pending=goAsync();WORKER.execute(()->{try{AppWidgetManager manager=AppWidgetManager.getInstance(context);int[] ids=manager.getAppWidgetIds(new ComponentName(context,getClass()));if(ids.length>0)update(context,manager,ids);}finally{pending.finish();}});}
 @Override public void onUpdate(Context context,AppWidgetManager manager,int[] ids){WORKER.execute(()->update(context,manager,ids));}
 @Override public void onDisabled(Context context){AlarmManager alarms=(AlarmManager)context.getSystemService(Context.ALARM_SERVICE);if(alarms!=null)alarms.cancel(refreshIntent(context));}
 public static void refreshAll(Context context){AppWidgetManager manager=AppWidgetManager.getInstance(context);for(Class<?> c:TYPES){int[] ids=manager.getAppWidgetIds(new ComponentName(context,c));if(ids.length>0)context.sendBroadcast(new Intent(context,c).setAction(AppWidgetManager.ACTION_APPWIDGET_UPDATE).putExtra(AppWidgetManager.EXTRA_APPWIDGET_IDS,ids));}}
 private PendingIntent refreshIntent(Context c){return PendingIntent.getBroadcast(c,getClass().getName().hashCode(),new Intent(c,getClass()).setAction(AppWidgetManager.ACTION_APPWIDGET_UPDATE),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private static int resource(Context c,String name,String type){return c.getResources().getIdentifier(name,type,c.getPackageName());}
 private static String text(Context c,String key,String ar,String en){int id=resource(c,"lp_"+key,"string");return id!=0?c.getString(id):"ar".equals(c.getResources().getConfiguration().getLocales().get(0).getLanguage())?ar:en;}
 private static String method(Context c,String id){String[] arrays={"kemenag_country","jakim_country","muis_country","diyanet_country","karachi_country","umm_qura","uoif_country","isna_country","egypt_country"};String[] methods={"at","jakim","muis","diyanet","karachi","uau","uiof","isna","ega"};for(int i=0;i<arrays.length;i++){int r=resource(c,"lp_"+arrays[i],"array");if(r!=0&&Arrays.asList(c.getResources().getStringArray(r)).contains(id))return methods[i];}return "mwl";}
 private static String name(Context c,String id){String key=id.equals("sunrise")?"shuruq":id.equals("dhuhr")?"duhr":id.equals("dhuha")?"duha":id;return text(c,key,id,id);}
 private static String time(Context c,SharedPreferences p,ReferencePrayer.Event event,ZoneId zone){ZonedDateTime d=event.instant.atZone(zone);Locale locale=c.getResources().getConfiguration().getLocales().get(0);boolean full=p.getInt("hours_format",android.text.format.DateFormat.is24HourFormat(c)?1:0)==1;return String.format(locale,full?"%02d:%02d":"%d:%02d",full?d.getHour():(d.getHour()+11)%12+1,d.getMinute())+(full?"":" "+text(c,d.getHour()<12?"am":"pm",d.getHour()<12?"ص":"م",d.getHour()<12?"AM":"PM"));}
 private void update(Context base,AppWidgetManager manager,int[] ids){manager.updateAppWidget(ids,render(base));}
 public RemoteViews render(Context base){Configuration config=new Configuration(base.getResources().getConfiguration());config.setLocales(Resources.getSystem().getConfiguration().getLocales());Context c=base.createConfigurationContext(config);SharedPreferences p=c.getSharedPreferences("layan_local",0);Locale locale=config.getLocales().get(0);RemoteViews views=new RemoteViews(c.getPackageName(),resource(c,"lp_widget_"+kind(),"layout"));views.setInt(resource(c,"lp_widget_root","id"),"setLayoutDirection",android.text.TextUtils.getLayoutDirectionFromLocale(locale));PendingIntent open=PendingIntent.getActivity(c,501,new Intent(c,PrayerActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);views.setOnClickPendingIntent(resource(c,"lp_widget_root","id"),open);
 boolean dark=android.preference.PreferenceManager.getDefaultSharedPreferences(c).getBoolean("nightMode",false);LayanUi.Palette palette=new LayanUi.Palette(c);int ink=palette.ink,muted=palette.muted,green=palette.green;views.setInt(resource(c,"lp_widget_root","id"),"setBackgroundResource",resource(c,dark?"lp_widget_background_dark":"lp_widget_background","drawable"));views.setTextColor(resource(c,"lp_widget_date","id"),ink);views.setTextColor(resource(c,"lp_widget_location","id"),muted);views.setTextColor(resource(c,"lp_widget_next","id"),green);views.setTextColor(resource(c,"lp_widget_countdown","id"),green);
 views.setViewVisibility(resource(c,"lp_widget_countdown","id"),View.VISIBLE);if(kind().equals("horizontal")||kind().equals("vertical"))views.setViewVisibility(resource(c,"lp_widget_times","id"),View.VISIBLE);
 try{if(c.checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&c.checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)throw new IllegalStateException("Location permission");double lat=Double.longBitsToDouble(p.getLong("prayer_lat",Double.doubleToLongBits(Double.NaN))),lon=Double.longBitsToDouble(p.getLong("prayer_lon",Double.doubleToLongBits(Double.NaN)));if(!Double.isFinite(lat)||!Double.isFinite(lon))throw new IllegalStateException("No saved location");GeoTimezone lookup=new GeoTimezone(c.getAssets().open("timezones/data.txt"),c.getAssets().open("timezones/zones.txt"));String found=lookup.lookup(lat,lon),chosen=p.getString("lp_zone","PHONE");ZoneId zone=PrayerTimeZone.resolve(chosen,found);String method=p.getString("lp_method","AUTO");if(method.equals("AUTO"))method=method(c,PrayerTimeZone.methodZone(chosen,found));int elevationMode=p.getInt("elevation_option",0);Object customElevation=p.getAll().get("elevation");double elevation=elevationMode==0?-9999:elevationMode==1?(customElevation instanceof Number?((Number)customElevation).doubleValue():20):p.getFloat("lp_altitude",0);ReferencePrayer engine=new ReferencePrayer(lat,lon,elevation,zone,method,p.getAll());Instant now=Instant.ofEpochMilli(System.currentTimeMillis());LocalDate date=now.atZone(zone).toLocalDate();List<ReferencePrayer.Event> events=engine.times(date);ReferencePrayer.Event next=engine.next(now);LocalDate hijriDate=date;if(p.getBoolean("hijri_at_maghrib",false))for(ReferencePrayer.Event e:events)if(e.id.equals("maghrib")&&!now.isBefore(e.instant))hijriDate=date.plusDays(1);int[] hijri=engine.hijri(hijriDate);String[] months={"muharram","safar","rabia_awal","rabia_thani","jumaada_awal","jumaada_thani","rajab","shaban","ramadan","shawwal","dhulqidah","dhulhijjah"};String gregorian=date.format(DateTimeFormatter.ofPattern("EEE, d MMM",locale)),islamic=String.format(locale,"%d %s",hijri[2],text(c,months[hijri[1]],months[hijri[1]],months[hijri[1]]));views.setTextViewText(resource(c,"lp_widget_date","id"),p.getInt("date_format",0)==0?gregorian+" • "+islamic:islamic+" • "+gregorian);views.setTextViewText(resource(c,"lp_widget_location","id"),p.getString("lp_location_name",zone.getId()));views.setTextViewText(resource(c,"lp_widget_next","id"),name(c,next.id)+" "+time(c,p,next,zone));views.setChronometerCountDown(resource(c,"lp_widget_countdown","id"),true);views.setChronometer(resource(c,"lp_widget_countdown","id"),SystemClock.elapsedRealtime()+Math.max(0,next.instant.toEpochMilli()-System.currentTimeMillis()),null,true);Bitmap moon=MoonView.bitmap(c,resource(c,"layan_prayer_moon","drawable"),engine.moon(now),LayanUi.FOREST);views.setImageViewBitmap(resource(c,"lp_widget_moon","id"),Bitmap.createScaledBitmap(moon,72,72,true));if(kind().equals("clock")){views.setString(resource(c,"lp_widget_clock","id"),"setTimeZone","GMT"+zone.getRules().getOffset(now).getId().replace("Z","+00:00"));views.setTextColor(resource(c,"lp_widget_clock","id"),green);}
 if(kind().equals("horizontal")||kind().equals("vertical")){String[] shown={"fajr","sunrise","dhuhr","asr","maghrib","isha"};for(int i=0;i<shown.length;i++){ReferencePrayer.Event event=null;for(ReferencePrayer.Event e:events)if(e.id.equals(shown[i]))event=e;boolean selected=event!=null&&event.instant.equals(next.instant);views.setInt(resource(c,"lp_widget_row"+i,"id"),"setBackgroundResource",selected?resource(c,"lp_widget_selected","drawable"):0);views.setTextViewText(resource(c,"lp_widget_name"+i,"id"),name(c,shown[i]));views.setTextViewText(resource(c,"lp_widget_time"+i,"id"),event==null?"—":time(c,p,event,zone));views.setTextColor(resource(c,"lp_widget_name"+i,"id"),selected?LayanUi.FOREST:ink);views.setTextColor(resource(c,"lp_widget_time"+i,"id"),selected?LayanUi.FOREST:ink);}}
 AlarmManager alarms=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(alarms!=null)alarms.set(AlarmManager.RTC,next.instant.toEpochMilli()+1000,refreshIntent(c));
 }catch(Exception e){android.util.Log.w("LayanWidget","Prayer widget needs location or settings",e);views.setTextViewText(resource(c,"lp_widget_date","id"),text(c,"prayer_times","مواقيت الصلاة","Prayer times"));views.setTextViewText(resource(c,"lp_widget_location","id"),text(c,"enable_location","افتح الصلاة لتحديد الموقع","Open prayer times to set location"));views.setTextViewText(resource(c,"lp_widget_next","id"),"");views.setChronometer(resource(c,"lp_widget_countdown","id"),SystemClock.elapsedRealtime(),null,false);views.setViewVisibility(resource(c,"lp_widget_countdown","id"),View.GONE);if(kind().equals("horizontal")||kind().equals("vertical"))views.setViewVisibility(resource(c,"lp_widget_times","id"),View.GONE);}
 return views;
 }
}
